// Node 9: Validate Structured JSON from Gemini
// Extracts generated subject, body, summary and validates all required fields.
const response = $input.first().json;
const leadCapture = $('FastAPI Ingestion (lead-capture)').first().json;
const leadData = $('Normalize Lead Data').first().json;

let parsed = null;
try {
  if (response.candidates && response.candidates[0]?.content?.parts?.[0]?.text) {
    parsed = JSON.parse(response.candidates[0].content.parts[0].text);
  } else if (response.subject && response.body && response.summary) {
    parsed = response;
  }
} catch (e) {
  return [{
    json: {
      is_valid_ai: false,
      error_reason: 'Malformed JSON returned from Gemini: ' + e.message,
      lead_id: leadCapture.lead_id,
      row_number: leadData.row_number
    }
  }];
}

if (!parsed || typeof parsed !== 'object') {
  return [{
    json: {
      is_valid_ai: false,
      error_reason: 'Gemini did not return an object',
      lead_id: leadCapture.lead_id,
      row_number: leadData.row_number
    }
  }];
}

const subject = (parsed.subject || '').trim();
const body = (parsed.body || '').trim();
const summary = (parsed.summary || '').trim();

if (!subject || !body || !summary) {
  return [{
    json: {
      is_valid_ai: false,
      error_reason: 'Gemini output missing required fields (subject, body, or summary)',
      lead_id: leadCapture.lead_id,
      row_number: leadData.row_number
    }
  }];
}

return [{
  json: {
    is_valid_ai: true,
    lead_id: leadCapture.lead_id,
    subject: subject,
    body: body,
    summary: summary,
    row_number: leadData.row_number,
    error_reason: null
  }
}];
